// Usage: node benchmarks/audit-sources.ts [benchmarks/results/research-N.json]
// Lists every search result each person's research run saw, from the saved SerpApi responses, with
// what the identity engine did with it and why. Saves benchmarks/results/sources-N.json for labeling:
// `right` is null until the user marks a result true (the stone's person) or false (someone else).
// A people.json case's own memorial is the one result known to be right before labeling.
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dropGated, gradePage, resolveMatches } from '../src/lib/server/identity.ts';
import { canonicalUrl } from '../src/lib/server/search/url.ts';
import type { Candidate, Inscription, SourceRecord } from '../src/lib/types.ts';

interface Row {
	file: string;
	inscription: Inscription;
	searches: string[];
	candidates: Candidate[];
}

type Verdict =
	| 'kept'
	| 'gated site'
	| 'no name or another initial'
	| 'date against stone'
	| 'weaker than a dated match'
	| 'over five sources';

const SAVED = 'fixtures/serp';
const RESULTS = 'benchmarks/results';
/**
 * Finds the highest run number saved under a result prefix.
 * @param prefix File prefix such as "research".
 * @returns The number, or 0 when none is saved.
 */
const newest = (prefix: string) =>
	Math.max(
		0,
		...readdirSync(RESULTS)
			.map((f) => new RegExp(`^${prefix}-(\\d+)\\.json$`).exec(f)?.[1])
			.filter(Boolean)
			.map(Number)
	);
const runFile = process.argv[2] ?? `${RESULTS}/research-${newest('research')}.json`;
const run = JSON.parse(readFileSync(runFile, 'utf8')) as { rows: Row[] };

const responses = new Map<string, { body?: { organic_results?: Record<string, string>[] } }>();
for (const f of readdirSync(SAVED).filter((x) => !x.startsWith('goto-'))) {
	const saved = JSON.parse(readFileSync(`${SAVED}/${f}`, 'utf8'));
	responses.set(`${saved.engine}: ${saved.query}`, saved);
}
const truth = new Map<string, string>(
	JSON.parse(readFileSync('fixtures/people.json', 'utf8')).map(
		(p: { file: string; source: string }) => [p.file, canonicalUrl(p.source)]
	)
);
const pages = new Map<string, string | null>(
	JSON.parse(readFileSync('fixtures/stories-recorded.json', 'utf8')).flatMap(
		(c: { pages: Record<string, string | null> }) => Object.entries(c.pages)
	)
);

/**
 * Resolves a Google redirect link from its saved hop.
 * @param link Result link.
 * @returns The page it leads to, or null.
 */
function page(link = ''): string | null {
	if (/^https?:/.test(link) && !link.includes('google.com/goto')) return link;
	const href = new URL(link, 'https://www.google.com').href;
	const file = `${SAVED}/goto-${createHash('sha256').update(href).digest('hex').slice(0, 16)}.json`;
	return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')).location : null;
}

const people = run.rows.map((row) => {
	const ins = row.inscription;
	const kept = new Set(row.candidates.flatMap((c) => c.sources.map((s) => canonicalUrl(s.url))));
	const dated = row.candidates.some((c) => c.confidence !== 'low');
	const hits = new Map<string, SourceRecord & { search: string }>();
	for (const search of new Set(row.searches))
		for (const r of responses.get(search)?.body?.organic_results ?? []) {
			const url = page(r.link);
			const key = url && canonicalUrl(url);
			if (!key || hits.has(key)) continue;
			const site = URL.parse(url)!.hostname;
			hits.set(key, { id: '', url, title: r.title ?? '', site, snippet: r.snippet ?? '', search });
		}
	const results = [...hits.entries()].map(([key, hit]) => {
		const alone = resolveMatches(ins, [hit])[0];
		const undated = resolveMatches({ ...ins, born: null, died: null }, [hit]).length > 0;
		let verdict: Verdict = 'kept';
		if (!kept.has(key)) {
			if (!dropGated([hit]).length) verdict = 'gated site';
			else if (!alone) verdict = undated ? 'date against stone' : 'no name or another initial';
			else if (dated && alone.confidence === 'low') verdict = 'weaker than a dated match';
			else verdict = 'over five sources';
		}
		const text = pages.get(hit.url);
		return {
			url: hit.url,
			search: hit.search.split(':')[0],
			query: hit.search.slice(hit.search.indexOf(':') + 2),
			title: hit.title,
			snippet: hit.snippet,
			grade: alone?.confidence ?? null,
			verdict,
			// What the fetched page proves, for kept results only: the story fetches nothing else.
			page:
				text === undefined
					? null
					: text === null
						? 'unreadable'
						: (gradePage(ins, text) ?? 'against or unnamed'),
			right: truth.get(row.file) === key ? true : null
		};
	});
	return { file: row.file, name: ins.name, born: ins.born, died: ins.died, results };
});

const out = `${RESULTS}/sources-${newest('sources') + 1}.json`;
writeFileSync(out, `${JSON.stringify({ run: runFile, people }, null, '\t')}\n`);

const all = people.flatMap((p) => p.results);
/**
 * Counts results.
 * @param pick Which results to count.
 * @returns How many match.
 */
const count = (pick: (r: (typeof all)[number]) => boolean) => all.filter(pick).length;
console.log(`${out}: ${all.length} results for ${people.length} people from ${runFile}`);
for (const v of [
	'kept',
	'gated site',
	'no name or another initial',
	'date against stone',
	'weaker than a dated match',
	'over five sources'
])
	console.log(`  ${v.padEnd(26)} ${count((r) => r.verdict === v)}`);
for (const p of people.filter((x) => truth.has(x.file))) {
	const own = p.results.find((r) => r.right);
	console.log(
		`  own memorial, ${p.name.padEnd(30)} ${own ? `${own.verdict} (${own.search})` : 'never returned'}`
	);
}
// Usage: node benchmarks/record-stories.ts [benchmarks/results/research-N.json]
// Freezes story inputs for the evals from a research benchmark run (the newest by default), so no
// search is sent: every candidate comes from SerpApi responses saved in fixtures/serp. Writes each
// person's candidates with the text of their sources to fixtures/stories-recorded.json. A page saved
// by an earlier recording is reused; only new pages are fetched, or every page with REFETCH=1.
// Labels start unreviewed: `match` is null until the user sets the index of the candidate who is
// the person on the stone, or -1 when none is. A label survives only while its candidates are unchanged.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fetchPage } from '../src/lib/server/pages.ts';
import type { Candidate, Inscription, Voice } from '../src/lib/types.ts';

interface Row {
	file: string;
	person: { voice: Voice };
	inscription: Inscription;
	candidates: Candidate[];
}

interface StoryCase {
	file: string;
	inscription: Inscription;
	candidates: Candidate[];
	pages: Record<string, string | null>;
	match: number | null;
	reviewed: false;
	voice: Voice;
}

const RESULTS = 'benchmarks/results';
const OUT = 'fixtures/stories-recorded.json';
const newest = readdirSync(RESULTS)
	.map((f) => /^research-(\d+)\.json$/.exec(f)?.[1])
	.filter(Boolean)
	.map(Number)
	.sort((a, b) => b - a)[0];
const runFile = process.argv[2] ?? `${RESULTS}/research-${newest}.json`;
const run = JSON.parse(readFileSync(runFile, 'utf8')) as {
	meta: { missing: string[] };
	rows: Row[];
};
if (run.meta.missing.length) throw new Error(`${runFile} ran without saved searches`);

const earlier = JSON.parse(readFileSync(OUT, 'utf8')) as StoryCase[];
// REFETCH=1 fetches every page again, for when text extraction changes.
const saved = new Map(
	process.env.REFETCH === '1' ? [] : earlier.flatMap((c) => Object.entries(c.pages))
);
/**
 * Keys a case by its fixture and person.
 * @param c A recorded case or research row.
 * @param c.file Fixture file.
 * @param c.inscription The person.
 * @returns The key.
 */
const key = (c: { file: string; inscription: Inscription }) =>
	`${c.file}|${c.inscription.carvedName}`;
const labels = new Map(earlier.map((c) => [key(c), c]));

const cases: StoryCase[] = [];
for (const row of run.rows) {
	const urls = [...new Set(row.candidates.flatMap((c) => c.sources.map((s) => s.url)))];
	const pages = Object.fromEntries(
		await Promise.all(
			urls.map(async (u) => [u, saved.has(u) ? saved.get(u)! : await fetchPage(u)] as const)
		)
	);
	const before = labels.get(key(row));
	const same = JSON.stringify(before?.candidates) === JSON.stringify(row.candidates);
	cases.push({
		file: row.file,
		inscription: row.inscription,
		candidates: row.candidates,
		pages,
		match: same ? (before?.match ?? null) : null,
		reviewed: false,
		voice: row.person.voice
	});
	console.error(
		`${row.inscription.name.padEnd(32)} ${row.candidates.length} candidates, ${urls.length} pages`
	);
}
writeFileSync(OUT, `${JSON.stringify(cases, null, '\t')}\n`);
console.error(`${OUT}: ${cases.length} cases from ${runFile}`);

