import { createScorer } from '@mastra/core/evals';
import { z } from 'zod';

const JUDGE_MODEL = 'google/gemini-3.8-flash';

/** What the story was written from: the person's name and every true text about them. */
export interface LifeClaimsInput {
	subject: string;
	context: string[];
}

const claimSchema = z.object({
	claim: z.string().describe('One claim, restated in plain words.'),
	kind: z.enum(['life', 'atmosphere', 'unsure']),
	evidence: z
		.string()
		.nullable()
		.describe('Exact words copied from the records that support the claim; null when none do.')
});

export type Claim = z.infer<typeof claimSchema>;

const JUDGE_INSTRUCTIONS = `<role>You audit a ghost story told at a grave for claims about a real person's life that the records do not support.</role>

<how_you_work>
- Split the story into every claim it makes, one per item. A sentence can hold several.
- kind "life": anything about the real person while alive: names, dates, ages, places, family, relationships, work, events, possessions, habits, traits, memories, and feelings about any of those.
- kind "atmosphere": the openly fictional frame: being a ghost, the grave, the dark, the weather, the visitor, the present moment, the afterlife.
- A claim that dresses a life detail in otherworld words is "life". "From beyond I watched my children grow" claims children.
- What is true of every dead person is "atmosphere": they lived, breathed, were born, died, and time has passed since. "I once breathed where you stand" claims nothing.
- How the life or death went is "life", and it holds when the records imply it. Died at 96: "a long life" holds. Died at 19: "gone too soon" holds. An organ donor: "pieces of me live on" holds. Died at 45: "a long life" is false.
- kind "unsure": you cannot tell whether the claim says something about the life. Use it instead of guessing.
- evidence: copy the exact words from the records that state the claim, or that it follows from directly. Copy, do not paraphrase.
</how_you_work>

<never>
- Never mark a claim "atmosphere" because it is poetic.
- Never give evidence that only makes a claim plausible. It must state the claim or prove it.
</never>`;

/**
 * Lowercases, drops replacement characters and collapses everything else but letters and digits
 * to single spaces.
 * @param s Text to normalize.
 * @returns Normalized text.
 */
function norm(s: string): string {
	return (
		s
			// Pages decoded with the wrong charset carry U+FFFD mid-word ("60�s"); the judge drops it.
			.replaceAll('\uFFFD', '')
			.toLowerCase()
			.replace(/[^\p{L}\p{N}]+/gu, ' ')
			.trim()
	);
}

/**
 * Finds claims that fail: every claim the judge was unsure of, and life claims whose evidence is
 * missing or not found word for word in the records. The judge names the evidence; this check keeps
 * it from vouching for words the records do not contain.
 * @param claims Claims the judge extracted.
 * @param context Records the story may draw on.
 * @returns Claims that needed support and the subset that failed.
 */
export function auditClaims(
	claims: Claim[],
	context: string[]
): { checked: Claim[]; unsupported: Claim[] } {
	const records = ` ${context.map(norm).join(' | ')} `;
	const checked = claims.filter((c) => c.kind !== 'atmosphere');
	const unsupported = checked.filter((c) => {
		const evidence = norm(c.evidence ?? '');
		return c.kind === 'unsure' || !evidence || !records.includes(` ${evidence} `);
	});
	return { checked, unsupported };
}

/**
 * Builds the scorer for life claims in a told story.
 * @param apiKey Gemini API key for the judge.
 * @returns A scorer: the share of checked claims backed by the records, 1 when the story makes none.
 */
export function lifeClaimsScorer(apiKey: string) {
	return createScorer<LifeClaimsInput, string>({
		id: 'life-claims',
		description: 'Every claim about the life of the person must be stated in the records.',
		judge: {
			model: { id: JUDGE_MODEL, apiKey },
			instructions: JUDGE_INSTRUCTIONS,
			modelSettings: { temperature: 0 }
		}
	})
		.analyze({
			description: 'Extract claims and the record text that supports each',
			outputSchema: z.object({ claims: z.array(claimSchema) }),
			createPrompt: ({ run }) =>
				`<records>\n${run.input!.context.join('\n---\n')}\n</records>\n\n<story subject="${run.input!.subject}">\n${run.output}\n</story>\n\nBased on the records above, list every claim the story makes.`
		})
		.generateScore(({ run, results }) => {
			const { checked, unsupported } = auditClaims(
				results.analyzeStepResult.claims,
				run.input!.context
			);
			return checked.length ? (checked.length - unsupported.length) / checked.length : 1;
		})
		.generateReason(({ run, results }) =>
			auditClaims(results.analyzeStepResult.claims, run.input!.context)
				.unsupported.map((c) => `${c.kind}: ${c.claim} (evidence: ${c.evidence ?? 'none'})`)
				.join('\n')
		);
}
import type { Inscription } from '../../src/lib/types.ts';

/**
 * Reads the whole year out of a stone date.
 * @param date Partial date as normalized, e.g. `1943-07-11`, `1943` or `19?3`.
 * @returns The year, or null when absent or not fully legible.
 */
function year(date: string | null): number | null {
	const y = date?.slice(0, 4) ?? '';
	return /^\d{4}$/.test(y) ? Number(y) : null;
}

/**
 * Finds years in a story that fall outside the life the stone records. The stone is the one source
 * known to be about this person, so a year before birth or after death means the records describe
 * someone else.
 * @param paragraph The story as told.
 * @param inscription The stone's person.
 * @param today Current date; a number past this year is a house number, not a year.
 * @returns Offending years, in order of appearance.
 */
export function yearsOutsideLife(
	paragraph: string,
	inscription: Inscription,
	today = new Date()
): number[] {
	const born = year(inscription.born) ?? -Infinity;
	const died = year(inscription.died) ?? Infinity;
	return [...paragraph.matchAll(/\b\d{4}\b/g)]
		.map((m) => Number(m[0]))
		.filter((y) => y <= today.getUTCFullYear() && (y < born || y > died));
}

/**
 * States the age at death the stone's dates prove, so a story may call the life long or short.
 * @param inscription The stone's person.
 * @returns A sentence, or null when either year is missing or not fully legible.
 */
export function ageAtDeath(inscription: Inscription): string | null {
	const born = year(inscription.born);
	const died = year(inscription.died);
	if (born === null || died === null) return null;
	// Without both full dates the birthday may not have come yet in the year of death.
	const exact = inscription.born!.length === 10 && inscription.died!.length === 10;
	const age =
		died - born - Number(exact && inscription.died!.slice(5) < inscription.born!.slice(5));
	return exact ? `I died at ${age} years old.` : `I died at about ${age} years old.`;
}
// Live eval: tells a story for every case on the real model and judges it. Page fetches replay the
// fixtures, so only the model calls are live. Run with `pnpm eval`.
// - stories-written.json: hand-written records that bait specific failures, always the right person.
// - stories-recorded.json: real search results, which may describe someone else until labeled.
import { afterAll, describe, expect, it, vi } from 'vitest';
import { epitaph } from '../../src/lib/epitaph.ts';
import { runStoneStory, runStory } from '../../src/lib/server/story.ts';
import type { Candidate, Inscription, Voice } from '../../src/lib/types.ts';
import { lifeClaimsScorer } from './life-claims.ts';
import { ageAtDeath, yearsOutsideLife } from './stone-years.ts';

interface StoryCase {
	inscription: Inscription;
	candidates: Candidate[];
	pages: Record<string, string | null>;
	match: number | null;
	reviewed: boolean;
	/** The narrator the person should get, whatever the name suggests. */
	voice: Voice;
	/** Hand-written stories that check the graders: `good` must pass, `bad` must fail. */
	good?: string;
	bad?: string;
}

// Hoisted above the imports, so node:fs is reached without one.
const { sets, env } = vi.hoisted(() => {
	const { readFileSync } = process.getBuiltinModule('node:fs');
	process.loadEnvFile('.env');
	/**
	 * Reads one fixture set.
	 * @param path Fixture file, relative to the repo root.
	 * @returns Its cases.
	 */
	const load = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as StoryCase[];
	return {
		sets: {
			written: load('fixtures/stories-written.json'),
			recorded: load('fixtures/stories-recorded.json')
		},
		env: { GEMINI_API_KEY: process.env.GEMINI_API_KEY }
	};
});
vi.mock('$app/env/private', () => env);
vi.mock('../../src/lib/server/pages.ts', () => ({
	fetchPage: async (url: string) =>
		[...sets.written, ...sets.recorded].find((c) => url in c.pages)?.pages[url] ?? null
}));

const scorer = lifeClaimsScorer(env.GEMINI_API_KEY ?? '');
const timings: number[] = [];
// Trial outcomes per set and person, for pass@1 (share of trials) and pass^3 (every trial).
const trials = new Map<string, Map<string, boolean[]>>();
// Narrator picks per set, kept apart from story trials so a wrong voice does not hide in them.
const voices = new Map<string, boolean[]>();
// The story model samples at temperature 1, so one passing draw proves little. A case passes only
// when every draw does.
const SAMPLES = 3;

/**
 * Picks the candidate the story is told about: the labeled match, else the top hit.
 * @param c Recorded case.
 * @returns The candidate, or undefined when research found none or none is the person.
 */
function told(c: StoryCase): Candidate | undefined {
	return c.match === -1 ? undefined : c.candidates[c.match ?? 0];
}

/**
 * Runs both graders on one paragraph.
 * @param c The case.
 * @param paragraph The story to grade.
 * @param fromRecords Whether the story was told from the candidate's records or the stone alone.
 * @returns Years outside the stone's life, the judge's score, and its reasons.
 */
async function grade(
	c: StoryCase,
	paragraph: string,
	fromRecords: boolean
