			const [inscription] = normalizeInscriptions([
				{ ...person, voice: null, place: WITH_PLACE ? asGeocoded(fixture.place) : null }
			]);
			const candidates = await runResearch(inscription);
			rows.push({
				file: fixture.file,
				reviewed: fixture.reviewed,
				person,
